#include <filesystem>
#include <string>

namespace tracker_file_ops {
namespace fs = std::filesystem;

enum class PathKind { missing, regular_file, unusable };
enum class PromotionMode { normal, simulate_failure_after_backup };

struct PromotionResult {
    bool promoted;
    bool rolled_back;
    std::string error;
    std::string warning;
};

inline PathKind inspect_regular_file(const fs::path& path, std::string& error) {
    std::error_code ec;
    const bool exists = fs::exists(path, ec);
    if (ec) {
        error = "cannot inspect " + path.string() + ": " + ec.message();
        return PathKind::unusable;
    }
    if (!exists) {
        return PathKind::missing;
    }
    const bool regular = fs::is_regular_file(path, ec);
    if (ec || !regular) {
        error = ec ? "cannot classify " + path.string() + ": " + ec.message()
                   : path.string() + " is not a regular file";
        return PathKind::unusable;
    }
    return PathKind::regular_file;
}

inline bool rename_checked(const fs::path& from, const fs::path& to, std::string& error) {
    std::error_code ec;
    fs::rename(from, to, ec);
    if (ec) {
        error = "rename " + from.string() + " -> " + to.string() + " failed: " + ec.message();
        return false;
    }
    return true;
}

inline bool remove_checked(const fs::path& path, std::string& error) {
    std::error_code ec;
    const bool removed = fs::remove(path, ec);
    if (ec || !removed) {
        error = ec ? "remove " + path.string() + " failed: " + ec.message()
                   : "remove " + path.string() + " failed: path was absent";
        return false;
    }
    return true;
}

inline PromotionResult promote_candidate(
    const fs::path& live,
    PromotionMode mode = PromotionMode::normal
) {
    const fs::path candidate{live.string() + ".tmp"};
    const fs::path backup{live.string() + ".bak"};
    std::string detail;

    if (inspect_regular_file(candidate, detail) != PathKind::regular_file) {
        return {false, false, "candidate is not a checked regular file: " + detail, ""};
    }

    detail.clear();
    const PathKind live_kind = inspect_regular_file(live, detail);
    if (live_kind == PathKind::unusable) {
        return {false, false, detail, ""};
    }

    detail.clear();
    const PathKind backup_kind = inspect_regular_file(backup, detail);
    if (backup_kind != PathKind::missing) {
        const std::string reason = backup_kind == PathKind::regular_file
            ? "stale backup exists; inspect it before retrying"
            : detail;
        return {false, false, reason, ""};
    }

    const bool moved_live = live_kind == PathKind::regular_file;
    if (moved_live && !rename_checked(live, backup, detail)) {
        return {false, false, detail, ""};
    }

    std::string promotion_error;
    const bool promoted = mode == PromotionMode::normal
        ? rename_checked(candidate, live, promotion_error)
        : false;
    if (mode == PromotionMode::simulate_failure_after_backup) {
        promotion_error = "simulated promotion failure for disposable test data";
    }

    if (!promoted) {
        if (!moved_live) {
            return {false, false, promotion_error, ""};
        }
        std::string rollback_error;
        if (rename_checked(backup, live, rollback_error)) {
            return {false, true, promotion_error, ""};
        }
        return {false, false, promotion_error + "; rollback also failed: " + rollback_error, ""};
    }

    if (moved_live) {
        std::string cleanup_error;
        if (!remove_checked(backup, cleanup_error)) {
            return {true, false, "", "promotion succeeded; " + cleanup_error};
        }
    }
    return {true, false, "", ""};
}
}

#include <iostream>
#include <string>

int checks_run{};
int failures{};

void check_true(const std::string& label, bool condition) {
    ++checks_run;
    if (condition) {
        std::cout << "PASS " << label << "\n";
    } else {
        std::cout << "FAIL " << label << "\n";
        ++failures;
    }
}

template <typename T>
void check_equal(const std::string& label, const T& actual, const T& expected) {
    ++checks_run;
    if (actual == expected) {
        std::cout << "PASS " << label << "\n";
    } else {
        std::cout << "FAIL " << label << ": expected " << expected
                  << ", actual " << actual << "\n";
        ++failures;
    }
}

